"""Shared Cosmos/dbt config for RideFlow DAGs."""

import os
from pathlib import Path

from cosmos import DbtTaskGroup, ExecutionConfig, ProfileConfig, ProjectConfig, RenderConfig
from cosmos.constants import LoadMode, TestBehavior

DBT_PROJECT_DIR = os.environ["DBT_PROJECT_DIR"]
# Generated by `dbt parse` in airflow-init (and `make dbt-parse`). Rendering the DAG from the
# manifest keeps DAG parsing fast; `dbt ls` at parse time can exceed the import timeout under load.
MANIFEST = Path(DBT_PROJECT_DIR) / "target" / "manifest.json"


def dbt_group(group_id: str, select: list[str]) -> DbtTaskGroup:
    """One Airflow task per dbt node; each model's tests run right after it and gate downstream."""
    use_manifest = MANIFEST.exists()
    return DbtTaskGroup(
        group_id=group_id,
        project_config=ProjectConfig(
            dbt_project_path=DBT_PROJECT_DIR,
            manifest_path=str(MANIFEST) if use_manifest else None,
        ),
        profile_config=ProfileConfig(
            profile_name="rideflow",
            target_name="dev",
            profiles_yml_filepath=f"{DBT_PROJECT_DIR}/profiles.yml",
        ),
        execution_config=ExecutionConfig(dbt_executable_path="/opt/airflow/dbt_venv/bin/dbt"),
        render_config=RenderConfig(
            load_method=LoadMode.DBT_MANIFEST if use_manifest else LoadMode.DBT_LS,
            select=select,
            test_behavior=TestBehavior.AFTER_EACH,
            # tests spanning 2+ models (relationships, raw↔fct reconciliation) run after *all* their parents
            should_detach_multiple_parents_tests=True,
        ),
    )
